import json
from unified_planning.io import PDDLReader
from unified_planning.shortcuts import PlanValidator
from unified_planning.io import PDDLReader

def validate_plan(domain_path, problem_path, plan_path):
    reader = PDDLReader()
    problem = reader.parse_problem(domain_path, problem_path)

    try:
        plan = reader.parse_plan(problem, plan_path)
    except Exception as e:
        print(f"Failed to parse plan {plan_path}: {e}")
        return False

    with PlanValidator(problem_kind=problem.kind) as validator:
        if not validator:
            print("No validator found!")
            return False
        result = validator.validate(problem, plan)

    return result.status.name == 'SOLVED_SATISFICING'

def main():
    with open("problem.json", "r") as f:
        tasks = json.load(f)

    all_passed = True
    for task in tasks:
        print(f"Validating {task['id']}...")
        if validate_plan(task['domain'], task['problem'], task['plan_output']):
            print(f"  {task['id']}: VALID")
        else:
            print(f"  {task['id']}: INVALID")
            all_passed = False

    if all_passed:
        print("All plans are valid.")
    else:
        print("Some plans are invalid.")

if __name__ == "__main__":
    main()

